// 取得台北時區的日期與時間
const now = new Date();
const timezone = 'Asia/Taipei';
const dateStr = now.toLocaleDateString('zh-TW', { timeZone: timezone, year: 'numeric', month: '2-digit', day: '2-digit' }).replace(/\//g, '-');
const timeStr = now.toLocaleTimeString('zh-TW', { timeZone: timezone, hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false });

return {
  json: {
    current_date: dateStr,
    current_time: timeStr,
    timestamp: now.toISOString(),
    timezone: timezone
  }
};

// 格式化日期為所需格式
const inputData = $input.first().json;
const currentDate = inputData.current_date;
const formattedDate = currentDate.replace(/-/g, '');

return {
  json: {
    ...inputData,
    formatted_date: formattedDate,
    display_date: currentDate,
    api_date: formattedDate
  }
};

// 直接在此節點重新計算台北時區的日期，確保日期數據可用
const now = new Date();
const timezone = 'Asia/Taipei';
const dateStr = now.toLocaleDateString('zh-TW', { timeZone: timezone, year: 'numeric', month: '2-digit', day: '2-digit' }).replace(/\//g, '-');
const formattedDate = dateStr.replace(/-/g, '');

// 獲取 Tableau token
const tableauAuth = $input.first().json;
let tableauToken = null;
try {
  if (tableauAuth.credentials) {
    tableauToken = tableauAuth.credentials.token || tableauAuth.credentials.sessionId;
  } else if (tableauAuth.token) {
    tableauToken = tableauAuth.token;
  }
} catch (error) {
  console.log('無法獲取 Tableau token:', error.message);
}

const TABLEAU_SITE_ID = "1b4032aa-745d-491e-93a6-847c7d77e26e";
const TABLEAU_BASE_URL = "https://prod-apnortheast-a.online.tableau.com/api/3.4";
const TOP100_VIEW_ID = "73f522ea-19fd-4e62-bafb-c0abe8755ec8";
const TOP5_GAME_VIEW_ID = "110c2b5c-107b-46b4-8f92-cb04f8678928";

// 數據源配置 - Top100 player 和 Top5 player_game 發送到兩個不同的 Slack channels
const dataSources = [
  {
    id: "top100_player_tableau",
    name: "Top100 player",
    viewId: TOP100_VIEW_ID,
    tableauWorkbook: "Top100-player.png",
    slackChannel: "C09RUT91SPL",
    description: "Top100 player 數據處理 - tableau_top100player channel",
    order: 2,
    sortOrder: "002"
  },
  {
    id: "top5_player_game_tableau",
    name: "Top5 player_game",
    viewId: TOP5_GAME_VIEW_ID,
    tableauWorkbook: "Top5-player_game.png",
    slackChannel: "C09RUT91SPL",
    description: "Top5 player_game 數據處理 - tableau_top100player channel",
    order: 4,
    sortOrder: "004"
  }
];

// 確保順序正確 - 按 order 排序
const sortedDataSources = dataSources.sort((a, b) => a.order - b.order);

console.log(`準備處理 ${sortedDataSources.length} 個數據源，按順序執行:`);
console.log(`當前日期: ${dateStr}`);
sortedDataSources.forEach((source, index) => {
  console.log(`${index + 1}. ${source.name} -> ${source.slackChannel} (order: ${source.order})`);
});

// 返回處理後的數據，確保順序和日期數據正確
const results = sortedDataSources.map((source, index) => ({
  json: {
    ...source,
    index: index + 1,
    total: sortedDataSources.length,
    date: formattedDate,
    displayDate: dateStr,  // 使用重新計算的日期
    startTime: now.toISOString(),
    status: 'pending',
    tableauToken,
    siteId: TABLEAU_SITE_ID,
    baseUrl: TABLEAU_BASE_URL,
    executionOrder: index + 1
  }
}));

return results;

